class _NotImplementedComparable(object):
    """Helper that supports rich comparisons with sympy objects only."""

    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        if isinstance(other, Basic):
            return self.value == other
        return NotImplemented

    def __ne__(self, other):
        if isinstance(other, Basic):
            return self.value != other
        return NotImplemented

    def __lt__(self, other):
        if isinstance(other, Basic):
            return True
        return NotImplemented

    def __gt__(self, other):
        if isinstance(other, Basic):
            return False
        return NotImplemented

    def __le__(self, other):
        if isinstance(other, Basic):
            return True
        return NotImplemented

    def __ge__(self, other):
        if isinstance(other, Basic):
            return False
        return NotImplemented

    def __hash__(self):
        return hash(self.value)


def test_compare_notimplemented():
    # Rich comparisons should return NotImplemented (not False) when the
    # other object's type is unknown, so that Python can delegate to the
    # reflected method on the other object (issue #22631).
    from sympy.abc import x
    f = _NotImplementedComparable(x)

    assert Basic.__eq__(x, f) is NotImplemented
    assert Basic.__ne__(x, f) is NotImplemented

    # delegation gives a symmetric relation
    assert (f == x) == (x == f) == True
    assert (f != x) == (x != f) == False

    # plain objects that cannot compare still yield False/True
    class Unknown(object):
        pass

    u = Unknown()
    assert (x == u) is False
    assert (u == x) is False
    assert (x != u) is True

    # equality between sympy objects is unaffected
    assert x == x
    assert x == symbols('x')
    assert not (x == symbols('y'))


