                             lambda x: True)
    object_hidden = getattr(env.config, 'viewcode_show_hidden', False)
    object_ignore = getattr(env.config, 'viewcode_ignore', [])

    for objnode in list(doctree.findall(addnodes.desc)):
        domain = objnode.get('domain')
        if domain != 'py':
