                        if ':' in child.astext() else (None, child.astext())
                elif isinstance(child, addnodes.desc_annotation):
                    if child.astext() in ('class', 'exception', 'function', 'method'):
                        info['type'] = child.astext()
                elif isinstance(child, addnodes.desc_addname):
                    modname, fullname = child.astext().split('.')[-2:]

