    elif app.builder.name.startswith('epub'):
        return
    if not env._viewcode_modules:
        return
    highlighter = app.builder.highlighter
    urito = app.builder.get_relative_uri

    for modname, entry in sorted(env._viewcode_modules.items()):
        filename, tags, lines = entry
        if not tags:
            continue
        a = ['<h2>Source code for %s</h2>' % modname]
        a.append('<pre>')
        for lineno, line in enumerate(lines):
            if lineno in tags:
                for tag, fullname in tags[lineno].items():
                    a.append('<span class="viewcode-block" id="%s"><a class="viewcode-back" '
                             'href="%s#viewcode.%s">[docs]</a>' %
                             (fullname, urito('index', 'viewcode:' + modname), fullname))
            if isinstance(line, tuple):
                if line[0] is None:
                    # the file does not exist on the filesystem, just a virtual file
                    a.append('<span class="ln">%6s </span>' % lineno)
                else:
                    href = '%s#L%d' % (line[0], line[1])
                    a.append('<span class="ln"><a href="%s" '
                             'rel="nofollow">%6d</a></span>' % (href, lineno + 1))
                line = line[2]
            else:
                a.append('<span class="ln">%6s </span>' % lineno)
            a.append(highlighter.highlight_block(line, 'python', linenos=False))
            if lineno in tags:
                a.append('</span>')
        a.append('</pre>')
        a.append('<div class="clearer"></div>')
        context = {
            'title': _('Source code for %s') % modname,
            'body': ('\n'.join(a)),
        }
